#!/usr/bin/env python3
"""Validation script for T14 pipeline outputs."""

import json
import os

OUTPUT_DIR = "outputs"
SUMMARY_FILE = os.path.join(OUTPUT_DIR, "t14_validation_summary.json")

def run_checks():
    """Run validation checks and return results."""
    results = []

    # Check 1: Selected indicators CSV exists and has expected columns
    check_name = "selected_indicators"
    file_path = os.path.join(OUTPUT_DIR, "t01_selected_indicators.csv")
    if os.path.exists(file_path):
        with open(file_path, "r") as f:
            lines = f.readlines()
        if len(lines) > 0:
            header = lines[0].strip().split(",")
            if "indicator" in header:
                results.append({
                    "check_name": check_name,
                    "passed": True,
                    "message": f"Selected indicators file exists with {len(lines)} rows and expected columns."
                })
            else:
                results.append({
                    "check_name": check_name,
                    "passed": False,
                    "message": f"Selected indicators file missing expected 'indicator' column."
                })
        else:
            results.append({
                "check_name": check_name,
                "passed": False,
                "message": "Selected indicators file is empty."
            })
    else:
        results.append({
            "check_name": check_name,
            "passed": False,
            "message": f"Selected indicators file not found: {file_path}"
        })

    # Check 2: Clean GTFS stops CSV exists and has valid structure
    check_name = "clean_gtfs_stops"
    file_path = os.path.join(OUTPUT_DIR, "t05_clean_stops.csv")
    if os.path.exists(file_path):
        with open(file_path, "r") as f:
            lines = f.readlines()
        if len(lines) > 0:
            header = lines[0].strip().split(",")
            required_cols = ["stop_code", "stop_name", "lat", "lon"]
            if all(col in header for col in required_cols):
                results.append({
                    "check_name": check_name,
                    "passed": True,
                    "message": f"Clean GTFS stops file exists with {len(lines)} rows and required columns."
                })
            else:
                results.append({
                    "check_name": check_name,
                    "passed": False,
                    "message": f"Clean GTFS stops file missing required columns: {required_cols}"
                })
        else:
            results.append({
                "check_name": check_name,
                "passed": False,
                "message": "Clean GTFS stops file is empty."
            })
    else:
        results.append({
            "check_name": check_name,
            "passed": False,
            "message": f"Clean GTFS stops file not found: {file_path}"
        })

    # Check 3: Clean POIs CSV exists and has valid structure
    check_name = "clean_pois"
    file_path = os.path.join(OUTPUT_DIR, "t08_pois_clean.csv")
    if os.path.exists(file_path):
        with open(file_path, "r") as f:
            lines = f.readlines()
        if len(lines) > 0:
            header = lines[0].strip().split(",")
            required_cols = ["poi_id", "name", "type"]
            if all(col in header for col in required_cols):
                results.append({
                    "check_name": check_name,
                    "passed": True,
                    "message": f"Clean POIs file exists with {len(lines)} rows and required columns."
                })
            else:
                results.append({
                    "check_name": check_name,
                    "passed": False,
                    "message": f"Clean POIs file missing required columns: {required_cols}"
                })
        else:
            results.append({
                "check_name": check_name,
                "passed": False,
                "message": "Clean POIs file is empty."
            })
    else:
        results.append({
            "check_name": check_name,
            "passed": False,
            "message": f"Clean POIs file not found: {file_path}"
        })

    # Check 4: Accessibility scores CSV exists and has valid structure
    check_name = "accessibility_scores"
    file_path = os.path.join(OUTPUT_DIR, "t10_accessibility_scores.csv")
    if os.path.exists(file_path):
        with open(file_path, "r") as f:
            lines = f.readlines()
        if len(lines) > 0:
            header = lines[0].strip().split(",")
            required_cols = ["poi_id", "accessibility_score"]
            if all(col in header for col in required_cols):
                results.append({
                    "check_name": check_name,
                    "passed": True,
                    "message": f"Accessibility scores file exists with {len(lines)} rows and required columns."
                })
            else:
                results.append({
                    "check_name": check_name,
                    "passed": False,
                    "message": f"Accessibility scores file missing required columns: {required_cols}"
                })
        else:
            results.append({
                "check_name": check_name,
                "passed": False,
                "message": "Accessibility scores file is empty."
            })
    else:
        results.append({
            "check_name": check_name,
            "passed": False,
            "message": f"Accessibility scores file not found: {file_path}"
        })

    # Check 5: City clusters CSV exists and has valid structure
    check_name = "city_clusters"
    file_path = os.path.join(OUTPUT_DIR, "t13_city_clusters.csv")
    if os.path.exists(file_path):
        with open(file_path, "r") as f:
            lines = f.readlines()
        if len(lines) > 0:
            header = lines[0].strip().split(",")
            required_cols = ["city_id", "cluster_id", "city_name"]
            if all(col in header for col in required_cols):
                results.append({
                    "check_name": check_name,
                    "passed": True,
                    "message": f"City clusters file exists with {len(lines)} rows and required columns."
                })
            else:
                results.append({
                    "check_name": check_name,
                    "passed": False,
                    "message": f"City clusters file missing required columns: {required_cols}"
                })
        else:
            results.append({
                "check_name": check_name,
                "passed": False,
                "message": "City clusters file is empty."
            })
    else:
        results.append({
            "check_name": check_name,
            "passed": False,
            "message": f"City clusters file not found: {file_path}"
        })

    return results

def main():
    """Main entry point."""
    results = run_checks()

    # Ensure output directory exists
    os.makedirs(OUTPUT_DIR, exist_ok=True)

    # Write summary to JSON file
    with open(SUMMARY_FILE, "w") as f:
        json.dump(results, f, indent=2)

    print(f"Validation complete. Summary written to {SUMMARY_FILE}")
    print(f"Total checks: {len(results)}")
    print(f"Passed: {sum(1 for r in results if r["passed"])}")
    print(f"Failed: {sum(1 for r in results if not r["passed"])}")

if __name__ == "__main__":
    main()

